/bin/bash -lc "node - <<'NODE'
const base = 'http://localhost:8080';
let token = null;
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
async function issueToken() {
  for (;;) {
    const res = await fetch(base + '/token', {method: 'POST'});
    if (res.status === 429) { await sleep((Number(res.headers.get('retry-after')) || 1) * 1000); continue; }
    if ("'!res.ok) throw new Error(`token HTTP ${res.status}`);
    token = (await res.json()).token;
    return;
  }
}
async function authed(path) {
  for (;;) {
    if (!token) await issueToken();
    const res = await fetch(base + path, {headers: {Authorization: `Bearer ${token}`}});
    if (res.status === 401) { token = null; continue; }
    if (res.status === 429) { await sleep((Number(res.headers.get('"'retry-after')) || 1) * 1000); continue; }
    if ("'!res.ok) throw new Error(`${path} HTTP ${res.status}`);
    return await res.json();
  }
}
const seen = new Set();
const qualifying = [];
let duplicates = 0;
let path = '"'/orders?page=1';
const start = Date.parse('2025-03-01T00:00:00Z');
const end = Date.parse('2025-06-01T00:00:00Z');
while (path) {
  const page = await authed(path);
  for (const order of page.items) {
    if (seen.has(order.id)) { duplicates++; continue; }
    seen.add(order.id);
    const placed = Date.parse(order.placed_at);
    if (order.status === 'shipped' && placed >= start && placed < end) qualifying.push(order);
  }
  path = page.next;
}
const customers = new Map();
const by_region = {north: 0, south: 0, east: 0, west: 0};
for (const order of qualifying) {
  let customer = customers.get(order.customer_id);
  if ("'!customer) { customer = await authed('"'/customers/' + encodeURIComponent(order.customer_id)); customers.set(order.customer_id, customer); }
  const discounted = Math.floor((order.amount_cents * (100 - customer.discount_pct) + 50) / 100);
  by_region[customer.region] += discounted;
}
const total_cents = Object.values(by_region).reduce((a,b) => a+b, 0);
console.log(JSON.stringify({total_cents, order_count: qualifying.length, duplicates_skipped: duplicates, by_region}, null, 2));
console.error(JSON.stringify({unique_listings: seen.size, customer_lookups: customers.size, qualifying: qualifying.length}));
NODE"

